/**
 * spellOnStack.test.js — the leaf's own arithmetic: a mana cost's value (CR 202.3, 202.3e/f/g) and a spell's mana value on the
 * stack (CR 202.3d — the half cast; CR 715.3b / 715.4 — an Adventure, or the adventurer cast normally; CR 202.3e — the announced
 * X, once per {X}). The game-level witnesses (counters, cast watchers, copies, the forced pick, Bolas's Citadel) are
 * stackManaValueReaders.test.js. Real oracle fixtures (bundled Scryfall, generated by cardIndex.publicCard).
 */
import { describe, expect, it } from "vitest";
import { manaCostValue, spellManaValue, stackSpellManaValue, spellMatchesCounterFilter } from "./spellOnStack.js";

const GELATINOUS_GENESIS = {"name":"Gelatinous Genesis","type":"Sorcery","mana":"{X}{X}{G}","cmc":1,"keywords":[],"colors":["G"],"oracle":"Create X X/X green Ooze creature tokens."}; // native-spell
const FIRE_ICE = {"name":"Fire // Ice","type":"Instant // Instant","mana":"{1}{R} // {1}{U}","cmc":4,"keywords":[],"layout":"split","colors":["R","U"],"oracle":"Fire - Instant {1}{R}\nFire deals 2 damage divided as you choose among one or two targets.\n//\nIce - Instant {1}{U}\nTap target permanent.\nDraw a card."}; // native-spell
const BEANSTALK_GIANT = {"name":"Beanstalk Giant // Fertile Footsteps","type":"Creature — Giant // Sorcery — Adventure","mana":"{6}{G} // {2}{G}","cmc":7,"keywords":[],"layout":"adventure","colors":["G"],"oracle":"Beanstalk Giant - Creature — Giant {6}{G}\nBeanstalk Giant's power and toughness are each equal to the number of lands you control.\n//\nFertile Footsteps - Sorcery — Adventure {2}{G}\nSearch your library for a basic land card, put it onto the battlefield, then shuffle. (Then exile this card. You may cast the creature later from exile.)","power":"*","toughness":"*"}; // native-mixed
const MENTAL_MISSTEP = {"name":"Mental Misstep","type":"Instant","mana":"{U/P}","cmc":1,"keywords":[],"colors":["U"],"oracle":"({U/P} can be paid with either {U} or 2 life.)\nCounter target spell with mana value 1."}; // native-spell

describe("manaCostValue (CR 202.3)", () => {
  it("generic counts its number, a hybrid symbol its largest component, a Phyrexian symbol 1, X nothing off the stack", () => {
    expect(manaCostValue("{3}{U}{U}")).toBe(5);       // CR 202.3's own example
    expect(manaCostValue("{2/B}{2/B}{2/B}")).toBe(6); // CR 202.3f's example
    expect(manaCostValue("{1}{W/U}{W/U}")).toBe(3);   // CR 202.3f's example
    expect(manaCostValue("{1}{W/P}{W/P}")).toBe(3);   // CR 202.3g's example
    expect(manaCostValue("{X}{X}{G}")).toBe(1);       // CR 202.3e — X is 0 off the stack
    expect(manaCostValue("")).toBe(0);
  });
});

describe("spellManaValue / stackSpellManaValue — the spell's mana value on the stack", () => {
  it("X counts once per {X} in the mana cost (CR 202.3e): Gelatinous Genesis for X = 3 is 7; a negative X counts nothing", () => {
    expect(spellManaValue(GELATINOUS_GENESIS, 3)).toBe(7);
    expect(spellManaValue(GELATINOUS_GENESIS, null)).toBe(1);
    expect(spellManaValue(GELATINOUS_GENESIS, -2)).toBe(1);
  });

  it("a split half is the half's cost (CR 202.3d); the whole card — a fused spell — is the combined cost", () => {
    const fire = { ...FIRE_ICE, name: "Fire", type: "Instant", mana: "{1}{R}" }; // splitCard.splitFaceCards' projection keeps the card's cmc
    expect(spellManaValue(fire)).toBe(2);
    expect(spellManaValue(FIRE_ICE)).toBe(4);
  });

  it("an Adventure is the Adventure's cost (CR 715.3b); the adventurer cast whole has its normal mana value (CR 715.4)", () => {
    const footsteps = { ...BEANSTALK_GIANT, name: "Fertile Footsteps", type: "Sorcery — Adventure", mana: "{2}{G}" };
    expect(spellManaValue(footsteps)).toBe(3);
    expect(spellManaValue(BEANSTALK_GIANT)).toBe(7);
  });

  it("a card without a printed number sums its cost; one with it reads it", () => {
    expect(spellManaValue({ name: "No number", type: "Instant", mana: "{2}{U}" })).toBe(3);
    expect(spellManaValue(MENTAL_MISSTEP)).toBe(1);
  });

  it("the stack object's X: its payload's params first (a program, a permanent, every copy), else the object's own stamp", () => {
    expect(stackSpellManaValue({ source: GELATINOUS_GENESIS, payload: { params: { xValue: 2 } } })).toBe(5);
    expect(stackSpellManaValue({ source: GELATINOUS_GENESIS, xValue: 4, payload: { resolver: "spell.noop", params: { cardName: "Gelatinous Genesis" } } })).toBe(9);
    expect(stackSpellManaValue({ source: GELATINOUS_GENESIS, payload: {} })).toBe(1);
  });
});

describe("spellMatchesCounterFilter — one filter for the enumeration and the resolution re-check", () => {
  it("reads the stack mana value: Mental Misstep's exact 1 refuses Gelatinous Genesis for X = 1 (3), takes it for X = 0", () => {
    const atom = { op: "counter", spellFilter: "any", targetType: "spell", exactMv: 1 };
    expect(spellMatchesCounterFilter({ source: GELATINOUS_GENESIS, payload: { params: { xValue: 1 } } }, "any", atom)).toBe(false);
    expect(spellMatchesCounterFilter({ source: GELATINOUS_GENESIS, payload: { params: { xValue: 0 } } }, "any", atom)).toBe(true);
  });
});
